#!/usr/bin/env python3
"""Профиль настроек у всех инструментов ОДИН — тот, который читает хост.

Откуда это взялось. Сборщик фактов уже научили уважать `CLAUDE_CONFIG_DIR`:
при заданной переменной всё, что документация зовёт `~/.claude`, живёт в
другом месте. Трое соседей об этом не знали и собирали путь литералом
`Path.home() / ".claude"` — доктор, ответ на «где я» и применение изменений.

Опаснее всех третий: он ПИШЕТ. На машине с назначенным профилем он правил
настройки в домашнем каталоге по диагнозу, собранному про другой каталог, а
копия для отката ложилась туда же, где её потом никто не искал. Правка в
одном профиле и копия в другом — это потеря данных с успешным кодом возврата.

Что здесь заперто:
  · при заданной переменной профиля каждый из троих работает с назначенным
    каталогом, а не с домашним, — и это проверяется наблюдаемым различием
    (разные разрешения, разные MCP-серверы, разный файл настроек на диске),
    а не тем, что в отчёте написано нужное слово;
  · адрес общего конфига хоста едет от того же профиля: имя каталога и
    список серверов приезжают из одного места, а не из двух разных;
  · прочитанный путь и ПРИЧИНА, по которой прочитан именно он, видны
    человеку: «в твоём профиле пусто» и «в чужом профиле пусто» — разные
    утверждения, и различает их только названный источник пути;
  · копия ложится в тот профиль, который правится, и откат находит её там же;
  · флаг паузы за назначенным профилем НЕ едет: его кладёт по домашнему
    адресу сам тормоз, и инструмент, ищущий его в другом месте, не «не нашёл
    паузу» — он её не соблюдает;
  · обратный контроль: без переменной поведение в точности прежнее.

Настоящий профиль человека здесь НЕ ЧИТАЕТСЯ ни разу. Окружение каждого
запуска собирается с нуля, а не наследуется: `HOME` указывает внутрь temp,
`PATH` пуст, каталог проекта задан явно, переменная профиля появляется только
там, где её проверяют. Иначе «зелёно» описывало бы машину, а не код.

Тест самодостаточен: только стандартная библиотека и сами инструменты.
"""
from __future__ import annotations

import json
import subprocess
import sys
import tempfile
import unittest
from pathlib import Path

РЕПО = Path(__file__).resolve().parents[2]
ИНСТРУМЕНТЫ = РЕПО / "plugins" / "superstack" / "tools"
ДОКТОР = ИНСТРУМЕНТЫ / "doctor.py"
ГДЕ_Я = ИНСТРУМЕНТЫ / "what.py"
ПРАВКА = ИНСТРУМЕНТЫ / "apply.py"

#: Имя переменной, которой хост переносит профиль настроек в другой каталог.
ПЕРЕМЕННАЯ = "CLAUDE_CONFIG_DIR"

#: Разрешения-мишени. Они РАЗНЫЕ в домашнем каталоге и в назначенном профиле:
#: совпади они — проверка перестала бы различать каталоги, ради которых
#: написана, и молча зеленела бы на любом из них.
ШИРОКОЕ_ДОМА = "Bash(docker *)"
ШИРОКОЕ_В_ПРОФИЛЕ = "Bash(curl *)"

#: MCP-серверы, по которым видно, из какого общего конфига читали. Имена взяты
#: из реестра вытеснения: доктор докладывает о них разными записями.
СЕРВЕР_ДОМА = "telegram"
ЗАПИСЬ_ДОМА = "third-party-messengers"
СЕРВЕР_В_ПРОФИЛЕ = "serena"
ЗАПИСЬ_В_ПРОФИЛЕ = "code-search-indexes"

#: Код, которым инструменты сообщают «система на паузе».
НА_ПАУЗЕ = 10


class Машина(unittest.TestCase):
    """Временная машина: домашний каталог, назначенный профиль, проект.

    Профиль лежит СВОИМ каталогом в стороне от домашнего. Иначе его общий
    конфиг оказался бы тем же файлом, что домашний, и проверка «взят у того же
    профиля» не различала бы ничего.
    """

    def setUp(self):
        tmp = tempfile.TemporaryDirectory()
        self.addCleanup(tmp.cleanup)
        self.корень = Path(tmp.name)
        self.дом = self.корень / "дом"
        self.домашний_профиль = self.дом / ".claude"
        self.профиль = self.корень / "рабочий" / ".claude"
        self.проект = self.корень / "проект"
        for каталог in (self.домашний_профиль, self.профиль, self.проект):
            каталог.mkdir(parents=True)

    # ---- фикстуры -----------------------------------------------------
    def записать(self, путь: Path, данные) -> Path:
        путь.parent.mkdir(parents=True, exist_ok=True)
        текст = данные if isinstance(данные, str) else json.dumps(
            данные, ensure_ascii=False)
        путь.write_text(текст, encoding="utf-8")
        return путь

    def прочитать(self, путь: Path):
        return json.loads(путь.read_text(encoding="utf-8"))

    def разрешение(self, правило: str) -> dict:
        return {"permissions": {"allow": [правило]}}

    def сервер(self, имя: str) -> dict:
        return {"mcpServers": {имя: {"command": "npx", "args": ["-y", имя]}}}

    # ---- запуск -------------------------------------------------------
    def запустить(self, инструмент: Path, *аргументы, профиль: Path = None,
                  тормоз: bool = False) -> subprocess.CompletedProcess:
        """Инструмент подпроцессом. Окружение собирается С НУЛЯ.

        Наследовать окружение человека нельзя: через него на инструмент
        протекает и его настоящий профиль, и его переменная профиля, — и тогда
        число зелёных тестов становится свойством машины.

        `тормоз=True` снимает признак «игнорировать паузу»: без этого проверка
        тормоза проверяла бы, что тормоз выключен.
        """
        среда = {
            "HOME": str(self.дом),
            "PATH": "",
            "SUPERSTACK_PROJECT_DIR": str(self.проект),
            "CLAUDE_CODE_ENTRYPOINT": "cli",
            "PYTHONUTF8": "1",
            "PYTHONIOENCODING": "utf-8",
        }
        if not тормоз:
            среда["SUPERSTACK_IGNORE_PAUSE"] = "1"
        if профиль is not None:
            среда[ПЕРЕМЕННАЯ] = str(профиль)
        return subprocess.run([sys.executable, str(инструмент), *аргументы],
                              env=среда, capture_output=True, text=True,
                              timeout=300)

    def доклад_доктора(self, профиль: Path = None) -> dict:
        p = self.запустить(ДОКТОР, "--json", "--offline", профиль=профиль)
        self.assertEqual(p.returncode, 0, p.stderr[-800:])
        return json.loads(p.stdout)

    def ответ_где_я(self, профиль: Path = None, тормоз: bool = False) -> dict:
        p = self.запустить(ГДЕ_Я, "--json", str(self.проект), профиль=профиль,
                           тормоз=тормоз)
        self.assertEqual(p.returncode, 0, p.stderr[-800:])
        return json.loads(p.stdout)


# ==========================================================================
# доктор
# ==========================================================================
class ДокторЧитаетНазначенныйПрофиль(Машина):
    """Сценарий (а) для осмотра: переменная задана — читается она."""

    def setUp(self):
        super().setUp()
        # Домашний каталог существует и НЕ ПУСТ: иначе «прочитали не тот» было
        # бы неотличимо от «там нечего читать».
        self.записать(self.домашний_профиль / "settings.json",
                      self.разрешение(ШИРОКОЕ_ДОМА))
        self.записать(self.дом / ".claude.json", self.сервер(СЕРВЕР_ДОМА))
        self.записать(self.профиль / "settings.json",
                      self.разрешение(ШИРОКОЕ_В_ПРОФИЛЕ))
        self.записать(self.профиль.parent / ".claude.json",
                      self.сервер(СЕРВЕР_В_ПРОФИЛЕ))
        self.доклад = self.доклад_доктора(self.профиль)

    def test_прочитан_назначенный_каталог(self):
        self.assertEqual(self.доклад.get("config_dir"), str(self.профиль),
                         "доктор доложил про каталог, в который не заглядывал")

    def test_источник_пути_назван(self):
        источник = self.доклад.get("config_dir_source") or ""
        self.assertIn(ПЕРЕМЕННАЯ, источник,
                      f"неясно, почему выбран этот каталог: {источник!r}")

    def test_разрешения_считаны_в_назначенном_профиле(self):
        правила = {з.get("rule") for з in self.доклад["config_security"]}
        self.assertIn(ШИРОКОЕ_В_ПРОФИЛЕ, правила, правила)
        self.assertNotIn(ШИРОКОЕ_ДОМА, правила,
                         "находка собрана в соседнем профиле")

    def test_общий_конфиг_взят_у_того_же_профиля(self):
        записи = {з.get("id") for з in self.доклад["supersession"]}
        self.assertIn(ЗАПИСЬ_В_ПРОФИЛЕ, записи, записи)
        self.assertNotIn(ЗАПИСЬ_ДОМА, записи,
                         "MCP-серверы приехали из профиля, о котором доклад не идёт")

    def test_человек_видит_профиль_и_причину(self):
        """Отчёт читают глазами, и он обязан сказать, о ЧЬИХ настройках он."""
        p = self.запустить(ДОКТОР, "--offline", профиль=self.профиль)
        self.assertEqual(p.returncode, 0, p.stderr[-800:])
        self.assertIn(str(self.профиль), p.stdout,
                      "прочитанный каталог не назван человеку")
        self.assertIn(ПЕРЕМЕННАЯ, p.stdout,
                      "причина, по которой прочитан этот каталог, не названа")


class ДокторБезПеременнойКакПрежде(Машина):
    """Обратный контроль: чинили выбор профиля, а не переписывали доктора."""

    def setUp(self):
        super().setUp()
        self.записать(self.домашний_профиль / "settings.json",
                      self.разрешение(ШИРОКОЕ_ДОМА))
        self.записать(self.дом / ".claude.json", self.сервер(СЕРВЕР_ДОМА))
        # Назначенный профиль на диске ЕСТЬ, но переменная не задана: читать
        # его никто не имеет права.
        self.записать(self.профиль / "settings.json",
                      self.разрешение(ШИРОКОЕ_В_ПРОФИЛЕ))
        self.доклад = self.доклад_доктора()

    def test_читается_домашний_каталог(self):
        self.assertEqual(self.доклад.get("config_dir"),
                         str(self.домашний_профиль))

    def test_источник_не_ссылается_на_незаданную_переменную(self):
        источник = self.доклад.get("config_dir_source") or ""
        self.assertNotIn(ПЕРЕМЕННАЯ, источник,
                         f"переменная не задана, а причина ссылается на неё: "
                         f"{источник!r}")

    def test_находки_из_домашнего_каталога(self):
        правила = {з.get("rule") for з in self.доклад["config_security"]}
        self.assertIn(ШИРОКОЕ_ДОМА, правила, правила)
        self.assertNotIn(ШИРОКОЕ_В_ПРОФИЛЕ, правила)

    def test_общий_конфиг_домашнего_профиля_прочитан(self):
        записи = {з.get("id") for з in self.доклад["supersession"]}
        self.assertIn(ЗАПИСЬ_ДОМА, записи, записи)


# ==========================================================================
# «где я»
# ==========================================================================
class ГдеЯНазываетПрофиль(Машина):
    """Ответ на «где я» обязан говорить, про какую систему он.

    Состояние без имени профиля нечем перепроверить: человек читает «работа не
    начата» и не может узнать, в чьём каталоге её искали.
    """

    def test_при_заданной_переменной_назван_назначенный_профиль(self):
        ответ = self.ответ_где_я(self.профиль)
        self.assertEqual(ответ.get("config_dir"), str(self.профиль))
        self.assertIn(ПЕРЕМЕННАЯ, ответ.get("config_dir_source") or "")

    def test_без_переменной_назван_домашний(self):
        ответ = self.ответ_где_я()
        self.assertEqual(ответ.get("config_dir"), str(self.домашний_профиль))
        self.assertNotIn(ПЕРЕМЕННАЯ, ответ.get("config_dir_source") or "")


class ТормозНеЕдетЗаПрофилем(Машина):
    """Флаг паузы кладут по домашнему адресу — там его и обязаны искать.

    Тормоз пишет `tools/pause.py`, и адрес у него один: домашний каталог.
    Инструмент, который ищет флаг в назначенном профиле, не «не нашёл паузу» —
    он её НЕ СОБЛЮДАЕТ. Цена ошибки здесь та же, что у тормоза вообще: он
    нужен ровно тогда, когда всё уже идёт не так.
    """

    def setUp(self):
        super().setUp()
        self.записать(self.дом / ".claude" / "superstack" / "PAUSE",
                      "2026-01-01T00:00:00Z\n")
        self.записать(self.профиль / "settings.json", {})

    def test_где_я_видит_паузу_при_назначенном_профиле(self):
        ответ = self.ответ_где_я(self.профиль, тормоз=True)
        self.assertEqual(ответ.get("reason"), "paused",
                         f"остановленная система названа работающей: {ответ}")

    def test_пишущий_инструмент_останавливается(self):
        p = self.запустить(ПРАВКА, "list", профиль=self.профиль, тормоз=True)
        self.assertEqual(p.returncode, НА_ПАУЗЕ,
                         f"инструмент, который ПИШЕТ, не увидел паузу: "
                         f"{p.stdout}{p.stderr}")
        self.assertIn("ОСТАНОВЛЕНО", p.stderr)


# ==========================================================================
# применение изменений
# ==========================================================================
class ПравкаИКопияВОдномПрофиле(Машина):
    """Сценарий (б): куда пишем — там и копия, и там же её ищет откат."""

    ПОЛЕ = "defaultMode"

    def setUp(self):
        super().setUp()
        self.записать(self.домашний_профиль / "settings.json", {})
        self.записать(self.профиль / "settings.json", {})
        self.находки = self.записать(self.корень / "находки.json", {"findings": [
            {"id": "ctx.default-mode-unset", "class": "AUTO", "verdict": "FIX",
             "headline": "режим прав не задан"}]})

    # ---- вспомогательное ----------------------------------------------
    def настройки(self, профиль: Path) -> dict:
        return self.прочитать(профиль / "settings.json")

    def режим(self, профиль: Path):
        return (self.настройки(профиль).get("permissions") or {}).get(self.ПОЛЕ)

    def копии(self, профиль: Path) -> list:
        каталог = профиль / "superstack" / "backups"
        return sorted(d.name for d in каталог.iterdir()) if каталог.is_dir() else []

    def применить(self, профиль: Path = None) -> subprocess.CompletedProcess:
        p = self.запустить(ПРАВКА, "run", str(self.находки), профиль=профиль)
        self.assertEqual(p.returncode, 0, p.stdout + p.stderr)
        return p

    # ---- проверки -----------------------------------------------------
    def test_правка_легла_в_назначенный_профиль(self):
        self.применить(self.профиль)
        self.assertEqual(self.режим(self.профиль), "plan",
                         "назначенный профиль не изменён")
        self.assertIsNone(self.режим(self.домашний_профиль),
                          "правка ушла в профиль, про который диагноз не собирали")

    def test_копия_лежит_в_том_же_профиле_что_и_правка(self):
        self.применить(self.профиль)
        self.assertEqual(len(self.копии(self.профиль)), 1,
                         "копии нет там, где лежит изменённый файл")
        self.assertEqual(self.копии(self.домашний_профиль), [],
                         "копия ушла в соседний профиль — откат её там не ищет")

    def test_откат_находит_копию_там_же(self):
        self.применить(self.профиль)
        имя = self.копии(self.профиль)[0]
        p = self.запустить(ПРАВКА, "undo", имя, профиль=self.профиль)
        self.assertEqual(p.returncode, 0, p.stdout + p.stderr)
        self.assertIsNone(self.режим(self.профиль),
                          "откат отчитался успехом, ничего не вернув")

    def test_профиль_назван_до_первого_изменения(self):
        """План существует затем, чтобы неожиданностей на шаге правки не было.

        Инструмент, который ПИШЕТ, обязан сказать КУДА, прежде чем это сделает.
        """
        p = self.запустить(ПРАВКА, "plan", str(self.находки), профиль=self.профиль)
        self.assertEqual(p.returncode, 0, p.stderr[-800:])
        self.assertIn(str(self.профиль), p.stdout,
                      "каталог, в который пойдёт правка, не назван")
        self.assertIn(ПЕРЕМЕННАЯ, p.stdout,
                      "причина, по которой выбран этот каталог, не названа")
        self.assertEqual(self.настройки(self.профиль), {},
                         "показ плана изменил файл")

    def test_без_переменной_всё_как_прежде(self):
        """Обратный контроль: домашний профиль правится и копируется как был."""
        self.применить()
        self.assertEqual(self.режим(self.домашний_профиль), "plan")
        self.assertEqual(len(self.копии(self.домашний_профиль)), 1)
        self.assertIsNone(self.режим(self.профиль),
                          "тронут профиль, о котором речи не было")
        self.assertEqual(self.копии(self.профиль), [])


if __name__ == "__main__":
    unittest.main()
